#!/usr/bin/env node

/**
 * Remove duplicate pages from the static export and redirect their URLs.
 *
 * Translations live next to the English page (src/pages/foo/bar.zh-CN.mdx), and
 * because pageExtensions includes 'mdx', Next.js also publishes each one as its
 * own route (/foo/bar.zh-CN). The real localized page is /zh-CN/foo/bar (the
 * proxy generated by scripts/generate-locale-pages.mjs), so the extra route is a
 * duplicate. This script runs after `next build`:
 *
 * - deletes out/**\/*.zh-CN.html and out/**\/*.ja-JP.html
 * - appends a 308 for each to out/_redirects (/foo/bar.zh-CN -> /zh-CN/foo/bar,
 *   /index.zh-CN -> /zh-CN)
 *
 * Run: node scripts/remove-duplicate-pages.mjs (part of `npm run build`)
 */

import { readdirSync, statSync, rmSync, appendFileSync, existsSync } from 'fs'
import { join, relative, sep } from 'path'

const OUT_DIR = join(import.meta.dirname, '..', 'out')
const LOCALES = ['zh-CN', 'ja-JP']
const pattern = new RegExp(`^(.*)[.](${LOCALES.join('|')})[.]html$`)

if (!existsSync(OUT_DIR)) {
  console.error('out/ not found - run next build first')
  process.exit(1)
}

function walk(dir, results = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry)
    if (statSync(full).isDirectory()) {
      if (entry === '_next' || LOCALES.includes(entry)) continue
      walk(full, results)
    } else if (pattern.test(entry)) {
      results.push(full)
    }
  }
  return results
}

const lines = []
for (const file of walk(OUT_DIR).sort()) {
  const rel = relative(OUT_DIR, file).split(sep).join('/')
  const [, base, locale] = rel.match(pattern)
  const from = `/${base}.${locale}`
  const to = base === 'index' ? `/${locale}` : `/${locale}/${base}`
  lines.push(`${from}  ${to}  308`)
  rmSync(file)
}

appendFileSync(
  join(OUT_DIR, '_redirects'),
  `\n# Duplicate translation routes (added by scripts/remove-duplicate-pages.mjs)\n${lines.join('\n')}\n`
)
console.log(`Removed ${lines.length} duplicate translation pages and added redirects.`)
